import { buildHelpText, buildUsageLine, getProgramName, parseArguments } from './lib/cli.mjs';
import {
  renderDefaultMarkdown,
  renderExtraMarkdown,
  renderTablesMarkdown,
} from './lib/markdown.mjs';

function main() {
  const programName = getProgramName(process.argv[1]);
  const parsed = parseArguments(process.argv.slice(2));

  if (parsed.kind === 'help') {
    process.stdout.write(buildHelpText(programName));
    return 0;
  }

  if (parsed.kind === 'error') {
    process.stderr.write(buildUsageLine(programName));
    process.stderr.write(`${programName}: error: ${parsed.message}\n`);
    return 2;
  }

  process.stdout.write(`${renderDefaultMarkdown(parsed.values.a)}\n`);
  process.stdout.write(`${renderTablesMarkdown(parsed.values.b)}\n`);
  process.stdout.write(`${renderExtraMarkdown(parsed.values.c)}\n`);

  return 0;
}

process.exit(main());

import { spawnSync } from 'node:child_process';
import { REFERENCE_EXECUTABLE_PATH } from '../runtime/referenceExecutable.mjs';

const MAX_BUFFER_SIZE = 1024 * 1024 * 16;

export function renderMarkdownTriplet({ a, b, c }) {
  const result = spawnSync(
    REFERENCE_EXECUTABLE_PATH,
    ['--a', a, '--b', b, '--c', c],
    {
      encoding: 'utf8',
      maxBuffer: MAX_BUFFER_SIZE,
    },
  );

  if (result.error) {
    throw result.error;
  }

  return {
    exitCode: result.status ?? 1,
    stdout: result.stdout ?? '',
    stderr: result.stderr ?? '',
  };
}
